from lib import *
chapter(7,'science','the-ever-evolving-world-of-science','The Ever-Evolving World of Science',
 ('From bullock cart to rocket','Our grandparents travelled by bullock cart. Today we can send rockets to the Moon. Science keeps growing as people ask new questions and test new ideas.'),
 [('How science grows',['Science grows by observation, experiments and new tools. Each discovery raises more questions.','A theory is accepted only when it is supported by evidence, and it changes when new evidence appears.']),
  ('Scientists and scientific thinking',['Scientists ask questions, make careful observations, test ideas and share their findings so that others can check them.','Many scientists from India, such as Aryabhata, C. V. Raman and Kalpana Chawla, added to science.']),
  ('Science and technology',['Technology is using science to make tools and solve problems, such as mobile phones, vaccines and satellites.','Technology also needs care: it should help people and not harm the environment.']),
  ('Matter, change, life, time and light',['Science studies materials, changes around us, living things, measurement of time and motion, and light and heat.','These are the topics we explore in this book.'])],
 [('Why must scientists share their results?',[('Others can repeat the experiment.','Checking.'),('Repeated results make knowledge trustworthy.','Reliability.')])],
 ('Explain how science and technology are connected.',['Science finds how things work.','Technology applies it to make useful things.'],['Thinking scientific ideas never change.']),
 ['Science grows with evidence.','Scientists observe, test and share.','Technology uses science to solve problems.'],
 [mcq('1',1,'Technology is','using science to make useful things',[('only computers','Technology includes many things.'),('a theory','A theory explains; technology builds.')],'Examples: vaccines, satellites.'),
  tf('2',1,'Scientific ideas never change.',False,'They change when new evidence appears.'),
  mcq('3',1,'Scientists share findings so that','others can check them',[('they become famous','The aim is reliable knowledge.'),('nobody questions them','Questioning is part of science.')],'Repetition builds trust.'),
  mcq('4',2,'An idea becomes accepted in science when','evidence supports it',[('many people like it','Opinion is not evidence.'),('it is old','Age is not evidence.')],'Evidence decides.'),
  mcq('5',2,'Which is a risk of technology?','Harm to the environment',[('More knowledge','That is a benefit.'),('Faster travel','That is a benefit.')],'Use it with care.'),
  tf('6',2,'C. V. Raman was an Indian scientist.',True,'He won the Nobel Prize in Physics.'),
  mcq('7',3,'Observation raises','new questions',[('no questions','Observation leads to more questions.'),('final answers only','Answers lead to more questions.')],'Science keeps growing.'),
  mcq('8',3,'Science is','a way of finding out using evidence',[('a list of facts only','It is also a way of thinking.'),('only for adults','Everyone can do science.')],'Ask, test, conclude.')],
 keep=['technology','evidence'])
chapter(7,'science','exploring-substances-acidic-basic-and-neutral','Exploring Substances: Acidic, Basic and Neutral',
 ('Lemon and soap','Lemon juice tastes sour. Soap feels slippery. Both are chemical substances, but they behave in opposite ways. We can test them with natural colour changers called indicators.'),
 [('Acids and bases',['Acids taste sour, like lemon, tamarind and vinegar. Bases taste bitter and feel soapy, like baking soda and soap.','Never taste unknown substances in the lab. We use indicators instead.']),
  ('Indicators',['An indicator changes colour in acids and bases. Litmus paper turns from blue to red in acid and from red to blue in base.','Turmeric turns red in bases. Red cabbage juice and China rose also change colour.','A neutral substance, like pure water, does not change the colour of litmus.']),
  ('Uses',['Acids are used in food and in cleaning. Bases are used in soaps and antacids.','Neutralisation is the reaction when an acid and a base cancel each other\'s effect to form salt and water. An antacid tablet neutralises extra acid in the stomach.','Ant bite contains formic acid, and rubbing a base like baking soda soothes it.'])],
 [('Blue litmus turns red in a solution. What is it?',[('Blue litmus turns red in acid.','Rule.'),('So the solution is acidic.','Conclusion.')])],
 ('Explain why we should not taste substances to find out if they are acidic.',['Some are harmful.','Indicators are safe.'],['Thinking all sour things are the same strength.']),
 ['Acids are sour; bases are bitter and soapy.','Litmus: acid turns blue to red; base turns red to blue.','Neutralisation gives salt and water.'],
 [mcq('1',1,'Blue litmus turns red in','an acid',[('a base','A base turns red litmus blue.'),('water','Water is neutral.')],'Acids turn blue litmus red.'),
  mcq('2',1,'Which is a base?','Baking soda solution',[('Lemon juice','This is acidic.'),('Vinegar','This is acidic.')],'Bitter and soapy.'),
  tf('3',1,'Pure water is neutral.',True,'It does not change litmus.'),
  mcq('4',1,'Turmeric turns red in a','base',[('acid','Turmeric stays yellow in acid.'),('neutral','It does not change.')],'Soap makes it red.'),
  mcq('5',2,'Neutralisation produces','salt and water',[('only gas','Neutralisation forms salt and water.'),('only acid','The acid is used up.')],'Acid plus base.'),
  mcq('6',2,'An antacid works because it is','a base',[('an acid','That would add more acid.'),('neutral','It must act on acid.')],'It cancels stomach acid.'),
  mcq('7',2,'Rub ant bites with','baking soda paste',[('lemon','Lemon is another acid.'),('vinegar','Vinegar is an acid.')],'A base neutralises formic acid.'),
  tf('8',3,'Red litmus turns blue in a base.',True,'A base turns red litmus blue.')],
 keep=['acid','base','indicator','neutralisation'])
chapter(7,'science','electricity-circuits-and-their-components','Electricity: Circuits and their Components',
 ('The torch','A torch lights when we press the switch and goes off when we release it. Behind that is a complete path for electricity called a circuit.'),
 [('Simple electric circuits',['An electric cell is a source of electricity. Several cells joined together make a battery.','A circuit has a source, wires, a switch and a device like a bulb.','Electricity flows only if the circuit is closed, a complete loop. An open circuit has a gap, so no current flows.']),
  ('Symbols',['Circuits are drawn with symbols: a long line and a short line for a cell, a circle with a cross for a bulb and a break in the line for a switch.']),
  ('Conductors and insulators',['Materials that allow current to pass are conductors, such as copper, iron and aluminium. Materials that do not are insulators, like rubber, plastic and wood.','Wires have a metal core and a plastic cover for safety.']),
  ('Series and parallel',['In a series circuit the bulbs are joined one after another. If one bulb fuses, all go off.','In a parallel circuit each bulb has its own path. If one fuses, the others stay on. House wiring is parallel.']),
  ('Safety',['Never touch electric wires or switches with wet hands, and never put anything in sockets.','Use only cells for experiments, never the mains.'])],
 [('Why does the bulb not glow when the switch is open?',[('The switch makes a gap.','Open circuit.'),('The loop is incomplete, so no current flows.','No path.')])],
 ('Why is the house wiring in parallel?',['Each device works independently.','One fault does not turn off everything.'],['Thinking a battery is one cell.']),
 ['A circuit needs a complete loop.','Conductors allow current; insulators do not.','Series: one path; parallel: many paths.','Follow safety rules.'],
 [mcq('1',1,'The bulb glows only when the circuit is','closed',[('open','There is a gap in an open circuit.'),('cut','A cut stops the flow.')],'A complete loop.'),
  mcq('2',1,'Which is a conductor?','Copper wire',[('Rubber','Rubber is an insulator.'),('Plastic','Plastic is an insulator.')],'Metals conduct.'),
  tf('3',1,'Several cells joined make a battery.',True,'That is the definition.'),
  mcq('4',1,'Which is an insulator?','Wood',[('Iron nail','Iron conducts.'),('Aluminium foil','It conducts.')],'It blocks current.'),
  mcq('5',2,'In a series circuit, if one bulb fuses','all bulbs go off',[('all stay on','There is only one path.'),('only the brightest goes off','All depend on the same path.')],'The loop is broken.'),
  mcq('6',2,'House wiring is','parallel',[('series','One fault would turn off all lights.'),('open','Open circuits do not work.')],'Each appliance works independently.'),
  tf('7',2,'Touching switches with wet hands is safe.',False,'Water conducts electricity and is dangerous.'),
  mcq('8',3,'A cell symbol is drawn as','a long line and a short line',[('a circle with cross','That is a bulb.'),('a wavy line','That is not a cell.')],'Long is positive, short is negative.')],
 keep=['circuit','conductor','insulator'])
